/* Voice allocation, envelopes, LFO and per-track rendering.
 * Runs in the audio ISR.
 *
 * Each synth part has its own NVOICE voices (so MONO / LEGATO / UNISON keep using
 * v[0..]), but only VOICE_BUDGET of all the parts' voices sound at once ((Skiff 1.3) NVOICE, 8; more with the second
 * core running: core.h): a part that starts
 * a voice while the budget is full takes one from any part (voice_victim): the oldest
 * released voice, else the oldest extra UNISON voice, else the oldest held voice of a
 * POLY part that is not its lowest note. A voice taken from another part fades out
 * over one block (stage 4: the envelope goes to 0, the block's amplitude ramp
 * declicks it); one of the part's own is restarted in place, as before. Extra UNISON
 * voices only start when there is room. */
static uint32_t vage;                                   /* voice ages: one clock for every part */
static int32_t lfo_wave(track_t *t, uint32_t ph)
{
    switch (t->p[P_LWAVE]) {
    case 1:
        return osc_tri(ph);
    case 2:
        return (int32_t)(ph >> 16) - 32768;
    case 3:
        return ph < 0x80000000u ? 32767 : -32767;
    case 4:
        return (int32_t)(t->lfo_rnd >> 16) - 32768;
    default:
        return osc_sine(ph);
    }
}

void sm_name(const char *name, uint32_t now, sm_send_fn send)
{
    uint8_t m[6 + 48];
    unsigned i, n = 5, same = 1;
    if (sm_name_hello) {               /* a hello (of either kind): send the name now, and keep it fresh 3 s */
        sm_name_hello = 0;
        sm_name_heard = now;
        sm_name_live = 1;
        sm_name_due = 1;
    }
    if (now - sm_name_heard >= SM_TIMEOUT) sm_name_live = 0;
    if (!sm_name_live) return;
    for (i = 0; i < sizeof sm_name_last - 1u && name[i]; ++i)
        if (sm_name_last[i] != name[i]) same = 0;
    if (sm_name_last[i]) same = 0;
    if (!same) {
        for (i = 0; i < sizeof sm_name_last - 1u && name[i]; ++i) sm_name_last[i] = name[i];
        sm_name_last[i] = 0;
        sm_name_due = 1;
    }
    if (!sm_name_due) return;
    m[0] = 0xf0; m[1] = 0x7d; m[2] = 'F'; m[3] = 'S'; m[4] = 2;
    for (i = 0; sm_name_last[i]; ++i) {
        uint8_t c = (uint8_t)sm_name_last[i];
        m[n++] = c < 0x20 || c > 0x7e ? (uint8_t)' ' : c;   /* 7-bit only (the header's middle dot: a space) */
    }
    m[n++] = 0xf7;
    i = (unsigned)send(m, n);
    if ((int)i == 0) sm_name_due = 0;  /* busy (-2) or not sent: again next time */
}

/* load the whole object into dst; returns its length, or -1 if it does not fit */
static int st_load(uint32_t obj, void *dst, uint32_t max)
{
    uint32_t i;
    st_hdr_t h;
    if (obj >= OBJ_COUNT || st_current(obj, &h) < 0 || h.len > max)
        return -1;
    for (i = 0; i < h.len; i++)
        ((uint8_t *)dst)[i] = st_buf[i];
    return (int)h.len;
}

/* (Skiff phase 6) the format of a record of n bytes if SKF2 (FELUCCA_LEGACY only), SKF3 or (2.0) SKF4 (a retained slot
 * too: its size in it); 0 not */
static const proj_fmt_t *proj_fmt_of(const void *b, int n)
{
    const uint32_t *w = (const uint32_t *)b;
    const proj_fmt_t *f = n < 8 ? 0 : w[0] == PROJ_MAGIC4 ? &PROJ_SKF4 : w[0] == PROJ_MAGIC3 ? &PROJ_SKF3 :
                          FELUCCA_LEGACY && w[0] == PROJ_MAGIC2 ? &PROJ_SKF2 : 0;
    return f && n >= (int)f->size && w[1] == f->size ? f : 0;
}

