static int settings_init(void)                 /* 1: no settings were kept (a new unit): the defaults */
{
    int fresh = 0;
    if (settings.magic == SETTINGS_MAGIC_OLD && settings.palette < 20u) {
        settings.magic = SETTINGS_MAGIC;
        settings.palette = palette_from_stored(settings.palette);
    }
    if (settings.magic != SETTINGS_MAGIC || settings.palette >= NPALETTES) {
        settings.magic = SETTINGS_MAGIC;
        settings.palette = UI_SKIFF_INDEX;     /* Skiff's look (main.c: STYLE BLOCKS with it); Felucca's: GREY */
        settings.lowcut = 0;
        settings.zoom = 0;                     /* (retired: the LEDS setting, settings_persist.c) */
        fresh = 1;
    }
    theme_apply();
    fx_lowcut = (uint8_t)(settings.lowcut % 3u);
    return fresh;
}

/* sine, linearly interpolated between the 1024 table points (plain lookup: THD -55 dB) */
static inline int32_t sine_i(uint32_t ph)
{
    uint32_t i = ph >> 22;
    int32_t a = SINE[i], b = SINE[(i + 1u) & 1023u];
    return a + (((b - a) * (int32_t)((ph >> 7) & 0x7FFFu)) >> 15);
}

static void track_defaults_steps(track_t *t)
{
    uint32_t i;
    motion_reset(t);
    for (i = 0; i < NSTEP; i++)
        step_clear(&t->step[i]);
}

/* the slot of copy seq while it holds the track as it was before its change (not undone, not gone), else -1 */
static int32_t undo_find(uint32_t seq)
{
    uint32_t a;
    for (a = undo_back; seq && a < undo_n; a++)
        if (undo_ring[(undo_top + UNDO_N - a) % UNDO_N].seq == seq)
            return (int32_t)((undo_top + UNDO_N - a) % UNDO_N);
    return -1;
}

static void load_begin(track_t *t, uint32_t what)
{
    uint32_t i = trk_index(t);
    if (what & UNDO_SOUND) {
        mom_back(t);                              /* ((1.3) MOMENTARY: the sound as it was, then the load) */
        drum_mute[i] = 0;                         /* ((1.3) the lanes' mutes go with the sound) */
    }
    if (undo_depth++)
        return;
    motion_restore(t);
    if (undo_n && !undo_back && undo.keep && undo.trk == i + 1u && !(undo.what & UNDO_MOT) &&
        track_sig(t) == undo.after) {
        if ((what & UNDO_KIT) && !(undo.what & UNDO_KIT))
            memcpy(undo.dx, dx_kit, sizeof undo.dx);   /* ((phase 7) the kit as it was, if not held already) */
        undo.what |= (uint8_t)what;               /* browsing on: the copy from before the first load stays */
        undo_label = 0;
        load_motion_hold(t, what);
        return;
    }
    undo_push(what);
    undo.trk = (uint8_t)(i + 1u);
    undo.what = (uint8_t)what;
    undo.eng = t->eng_req;
    undo.preset = t->preset;
    undo.user = t->user;
    memcpy(undo.p, t->p, sizeof undo.p);
    memcpy(undo.step, t->step, sizeof undo.step);
    memcpy(undo.fm6, fm6_patch[i], FP_SIZE);
    undo.fm6_slot = fm6_slot[i];
    if (what & UNDO_KIT)
        memcpy(undo.dx, dx_kit, sizeof undo.dx);
    undo.pid = trk_pid[i];
    motion_snapshot_track(t, &undo.motion_backup);
    load_motion_hold(t, what);
}

static uint32_t motion_count(const track_t *t)
{
    uint32_t i, n = 0, k = trk_index(t);
    for (i = 0; i < motion.count; i++) n += (motion.event[i].place >> 6) == k;
    return n;
}

/* e's preset pi (preset_orig's) into the values p: all but param_kept's ((2.0, #30) bank.c esnd_make's too) */
static void preset_fill(int16_t *p, const engine_t *e, uint32_t pi)
{
    uint32_t i;
    for (i = 0; i < P_E0; i++)                        /* the rest of the sound to its defaults: a preset */
        if (!param_kept(i))                           /* sounds the same after any edit */
            p[i] = TP[i].def;
    for (i = 0; i < 8u; i++)
        p[P_E0 + i] = (int16_t)e->presets[pi].e[i];
    p[P_ATK] = e->presets[pi].env[0];
    p[P_DEC] = e->presets[pi].env[1];
    p[P_SUS] = e->presets[pi].env[2];
    p[P_REL] = e->presets[pi].env[3];
    p[P_ED_FLT] = e->presets[pi].fenv;
    p[P_VOICE] = e->presets[pi].mono ? V_LEGATO : V_POLY;   /* mono presets keep the legato feel */
    {   /* the sends */
        static const uint8_t FX_DEF[4] = {0, 24, 28, 36};
        const preset_t *pr = &e->presets[pi];
        for (i = 0; i < 4u; i++)
            p[P_DIST + i] = (int16_t)(pr->fx[i] ? pr->fx[i] - 1 : FX_DEF[i]);
        for (i = 0; i < NELEM(pr->more) && pr->more[i].id; i++)   /* ((Skiff) its LFO, GLIDE, ..: core.h) */
            p[pr->more[i].id] = pr->more[i].v;
    }
}

static const slc_man_t *slc_man_of(const slc_src_t *s)
{
    uint32_t k = slc_slot_of(s);
    const slc_man_t *m;
    if (k >= SMP_USER_SLOTS)
        return 0;
    m = &slc_man[k][slc_man_cur[k] & 1u];
    return m->n ? m : 0;
}

static int st_erase(uint32_t off)
{
    if (off < SMP_USER_BASE || off + 0x1000u > SMP_USER_BASE + sizeof host_slots || (off & 0xFFFu))
        return -8;
    memset((uint8_t *)host_slots + (off - SMP_USER_BASE), 0xFF, 0x1000u);
    host_erases++;
    return 0;
}

static const param_desc_t *track_desc(const track_t *t, uint32_t id)
{
    if (id >= P_IA && id <= P_IC)                     /* ((1.3) the INSERT's values as its TYPE names them) */
        return ins_desc(t->p[P_ITYPE], id - P_IA);
    if (t->p[P_ESYNC] && (id == P_ATK || id == P_DEC || id == P_REL))   /* ((1.3) ENV SYNC: note values) */
        return &ESYNC_DESC[id == P_ATK ? 0 : id == P_DEC ? 1 : 2];
    if (id >= P_E0 && id <= P_E7) {                   /* the engine asked for (t->engine follows after a fade) */
        const engine_t *e = ENGINES[eng_idx(t->eng_req)];
        const param_desc_t *d = e->desc ? e->desc(t, id - P_E0) : 0;   /* a mode-dependent label / names */
        return d ? d : &e->edit[id - P_E0];
    }
    return &TP[id];
}

/* a step as FUN7..FUN9 / SKF1 store it, 9 bytes: its four notes (bit 7 of each: (Skiff) a bit of the trig condition),
 * the meta byte (n, time, accent, slide; bit 7 (Skiff) FLAM), velocity, the lane hits and their accents, the chance;
 * RATCH in bit 7 of the velocity and chance bytes (see the top). What step_get9 checks, so what is stored always
 * loads: 0 for a step no format can hold. (Skiff: the pattern bank, bank.c, stores steps the same way) */
static int step_put9(uint8_t *b, const step_t *s)
{
    uint32_t r = step_ratchet(s) - 1u, j;
    if (s->n > 4u || s->time > ST_REST || (s->flags & ~(3u | SF_RATCH | SF_FLAM)) || s->probability > 101u ||
        s->cond >= TC_COUNT || s->nudge < NUDGE_MIN || s->nudge > NUDGE_MAX)
        return 0;
    for (j = 0; j < 4u; j++)
        b[j] = (uint8_t)((s->note[j] > 127u ? 127u : s->note[j]) | ((s->cond >> j) & 1u) << 7);
    b[4] = (uint8_t)(s->n | s->time << 3 | (s->flags & 3u) << 5 | ((s->flags & SF_FLAM) ? 128u : 0u));
    b[5] = (uint8_t)((s->vel > 127u ? 127u : s->vel) | (r & 1u) << 7);
    b[6] = s->hit;
    b[7] = (uint8_t)(s->hit ? s->acc & s->hit : step_ties(s));   /* ((2.0, #25) no hits: the per-note ties) */
    b[8] = (uint8_t)(s->probability | (r >> 1) << 7);
    return 1;
}

static uint32_t ret_mode(void)
{
    return RET_BYTE <= RET_BAR ? RET_BAR - RET_BYTE : RET_BAR;
}

static const char *menu_vname(uint32_t row, uint32_t v)
{
    const menu_flag_t *f = menu_flag(row);
    if (f)
        return f->name[v & 1u];
    switch (row) {
    case MI_COLOR: return v < NPALETTES ? UI_PALETTES[v].name : "CUSTOM";
    case MI_PHEAD: return v & 1u ? "LINE" : "THEME";
    case MI_LOWCUT: return SPK_EQ[v % 3u];
    case MI_HOLD: return HOLD_N[v & 3u];
    case MI_CLICK: return CLICK_N[v % 3u];
    case MI_CLKLVL: return CLKLVL_N[v % 3u];
    case MI_COUNTIN: return COUNTIN_N[v % 3u];
    case MI_SCROFF: return SCROFF_N[v % NELEM(SCROFF_N)];
    case MI_LEDS: return LEDS_NAME[LEDS_MENU[v % LEDS_COUNT]];
    case MI_CLOCK: return N_CLOCK[v % NELEM(N_CLOCK)];
    case MI_ROUTE:                                     /* ((1.3) CH1-6 with a track set elsewhere: TRACK) */
        if (!(v & 1u) && (ui_mch(0) | ui_mch(1) | ui_mch(2) | ui_mch(3) | ui_mch(4) | ui_mch(5)))
            return "TRACK";
        return N_ROUTE[v & 1u];
    case MI_LCLEAR: case MI_TCH1: case MI_TCH2: case MI_TCH3: case MI_TCH4: case MI_TCH5: case MI_TCH6: {
        static char c[8] __attribute__((section(".pool")));   /* ((1.3) "CH 10"; LEARN CLEAR: "3 CC", "NONE") */
        if (row == MI_LCLEAR && !ml_count())
            return "NONE";
        str_cpy(c, row == MI_LCLEAR ? "" : "CH ", sizeof c);
        fmt_int(c + str_len(c), row == MI_LCLEAR ? (int32_t)ml_count() : (int32_t)v + 1);
        str_cpy(c + str_len(c), row == MI_LCLEAR ? " CC" : "", sizeof c - str_len(c));
        return c;
    }
    case MI_LEARN: return ui.ml.on ? "ON" : "";
#if BOARD_SMK37
    case MI_KVEL: return KVEL_N[v % SMK_KV_N];
#endif
    case MI_HINTS: return v & 1u ? "OFF" : "ON";
    case MI_PREVIEW: return v & 1u ? "ON" : "OFF";
    case MI_RETURN: return RET_N[v % 3u];
    case MI_TUNE: case MI_CPU: {                       /* "+12 CT"; the audio's share of each half-buffer ("14 %") */
        static char b[20] __attribute__((section(".pool")));
        int32_t c = row == MI_TUNE ? (int32_t)v - 50 : (int32_t)(song.cpu_q8 * 100u / 256u);
