    if (!s->n && !s->hit)
        s->time = ST_NOTE;
    if (!s->hit)
        s->acc = (uint8_t)((s->acc & ~(1u << s->n)) | (tie ? 1u << s->n : 0u));
    s->note[s->n++] = (uint8_t)p;
    return 1;
}

