}

static void ui_draw_page(uint32_t counting)
{
    if (ui.uboot) {
        draw_uboot();
        draw_head();
        return;
    }
    if (ui.menu) {
        draw_menu();
        ui.force = 0;
        return;
    }
    if (counting && !ui.confirm && !name_on()) {        /* the count-in: over the page (and a layer) */
        draw_countin();
        draw_head();
        return;
    }
    if (ui.confirm) {                                   /* the OCT- / OCT+ dialog */
        if (ui.force) {
            draw_confirm();
            ui.force = 0;
        }
        draw_head();                                    /* recording remains visible over confirmations */
        return;
    }
    if (name_on()) {                                    /* NAME: a user preset's or a project's (ui_name.c) */
        name_draw();
        return;
    }
    if (ui.layer || ui.shift) {                         /* a layer's map over the page (ui_layer.c); (Skiff U5, A1) SHIFT's,
                                                         * under the page's cards */
        if (ui.force)
            draw_frame();
        draw_head();
        if (ui.layer)
            draw_layer();
        else {
            draw_columns();
            draw_shift();
        }
        if (ui.msg_t && !--ui.msg_t && ui.msg2[0]) {
            str_cpy(ui.msg, ui.msg2, sizeof ui.msg);
            ui.msg2[0] = 0;
            ui.msg_t = MSG_T;
        }
        if (ui.hot_t)
            ui.hot_t--;
        if (ui.bpm_t)
            ui.bpm_t--;
        ui.force = 0;
        return;
    }
    if (!ui.home && !page_visible(ui.page)) {          /* a page the track no longer has (another track, another
                                                         * engine): (Skiff U3, N3) its family's first, or HOME, and why */
        uint32_t f = page_vis_first(PAGES[ui.page].fam);
        page_none(PAGES[ui.page].title);
        if (f < NPAGES) {
            ui.page = (uint8_t)f;
            page_entered();
        } else {
            go_home();
        }
    }
    cursor_fix();
    if (ui.force)
        draw_frame();
    felucca_dbg.stage = 3;
    draw_head();
    felucca_dbg.stage = 4;
    draw_columns();
    felucca_dbg.stage = 5;
    draw_graph();
    if (ui.msg_t && !--ui.msg_t && ui.msg2[0]) {     /* the second message (ui_notices) */
        str_cpy(ui.msg, ui.msg2, sizeof ui.msg);
        ui.msg2[0] = 0;
        ui.msg_t = MSG_T;
    }
    if (ui.bpm_t)
        ui.bpm_t--;
    if (ui.hot_t)
        ui.hot_t--;
    felucca_dbg.stage = 6;
    draw_foot();
    ui.force = 0;
}

static void fm6_penv_advance(fm6_penv_t *e, const uint8_t *p, uint32_t ix)
{
    e->ix = (uint8_t)ix;
    if (ix < 4u) {
        e->target = FM6_PENV_TAB[p[FP_PL1 + ix] % 100u] * (1 << 19);
        e->rising = e->target > e->level;
        e->inc = FM6_PENV_RATE[p[FP_PR1 + ix] % 100u] * FM6_PENV_UNIT;
    }
}

/* the ADSR (ONE: no release), DECAY, the fade at the slice end */
static int32_t slice_amp(track_t *t, voice_t *v, int32_t adsr)
{
    const int16_t *p = t->p;
    if (p[P_E4] == SLC_ONE && v->stage == 3u && ((uint32_t)v->s[4] & 7u) != SLC_SINE)
        v->stage = 2;                                   /* ONE: the slice plays to its end (the sine has none) */
    if (p[P_E6] < 127) {
        v->s[5] -= mulq16(v->s[5], ENV_EXP[p[P_E6] & 127]);
        if (v->s[5] < 8)
            v->s[6] = 2;                                /* faded out: the voice ends */
    }
    return v->s[6] == 3 ? 0 : mulq15(adsr, v->s[5]);
}

/* a bar of w px for v (0..127), then its text right at x + 84 */
static void dx_row_bar(int32_t x, int32_t w, int32_t y, int32_t rh, uint32_t v, uint16_t col, uint16_t bg, const char *txt)
{
    cv_rect(x, y + (rh - 4) / 2, w, 4, T_RAISE);
    cv_rect(x, y + (rh - 4) / 2, (int32_t)v * w / 127, 4, col);
    GFX_HOOK_ALIGN(0, y, 0, y + rh, AL_V, "DRUM-X sheet number on its row's middle");
    cv_text_r(x + 84, y + CAP_IN(S, rh), &AF_S, txt, T_MID, bg);
}

/* the patch as it plays (the macros), its algorithm, carriers and sounding operators */
static void fm_ops(fm_sim_t *s, const track_t *t)
{
    uint32_t k;
    memcpy(s->q, fm6_patch[trk_index(t) % NTRK], FP_SIZE);
    s->alg = fm6_alg_of(t);
    s->fb = (uint32_t)clamp((int32_t)s->q[FP_FB] + t->p[P_E1], 0, 7);
    fm6_macro(s->q, s->alg, &t->p[P_E0]);
    s->car = fm6_car_ops(s->alg);
    s->live = 0;
    for (k = 0; k < 6u; k++)
        s->live |= (uint32_t)(s->q[(5u - k) * FP_OP + FP_OL] != 0) << k;
    s->modlvl = clamp(t->p[P_E2], -64, 63) * 24 << 8;   /* (fm6_render: microsteps of 1/32 of an outlevel step) */
}

/* "12 MS", "0.67 S", "4.3 S" (blocks of 32 samples at 44.1 kHz) */
static void fm_secs(char *b, int32_t blocks)
{
    int32_t ms = blocks * 1000 / 1378;
    if (ms < 100) {
        fmt_int(b, ms < 1 ? 1 : ms);
        str_cpy(b + str_len(b), " MS", 4);
    } else if (ms < 1000) {
        fm_hundredths(b, ms / 10);
        str_cpy(b + str_len(b), " S", 3);
    } else {
        fm_tenths(b, ms / 100, 0);
        str_cpy(b + str_len(b), " S", 3);
    }
}

static void span_names(const card_span_t *sp, int32_t v, char *val, const char **unit)
{
    str_cpy(val, ((const char *const *)sp->p)[v], 12);
    *unit = "";
}
